\documentclass{article}
% Portrait A0: 841mm x 1189mm
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\pagestyle{empty}

% ── Dark Data-Dashboard Color Theme ──
\definecolor{bgdark}{HTML}{0B1120}
\definecolor{bgcard}{HTML}{111B2E}
\definecolor{bgcardalt}{HTML}{152035}
\definecolor{primary}{HTML}{0EA5E9}
\definecolor{primarydark}{HTML}{0284C7}
\definecolor{secondary}{HTML}{3B82F6}
\definecolor{accent}{HTML}{10B981}
\definecolor{accentbright}{HTML}{34D399}
\definecolor{gold}{HTML}{F59E0B}
\definecolor{goldbg}{HTML}{1A1608}
\definecolor{textwhite}{HTML}{F1F5F9}
\definecolor{textsecondary}{HTML}{94A3B8}
\definecolor{textmuted}{HTML}{64748B}
\definecolor{border}{HTML}{1E293B}
\definecolor{borderbright}{HTML}{334155}
\definecolor{greenbg}{HTML}{052E16}
\definecolor{bluebg}{HTML}{0C1A3A}
\definecolor{statbg}{HTML}{0F1D32}
\definecolor{tablebg}{HTML}{0D1526}
\definecolor{tablerow}{HTML}{111D33}
\definecolor{tablerowalt}{HTML}{0F172A}
\definecolor{titlebg}{HTML}{0C1930}
\definecolor{rank1bg}{HTML}{14253D}

\pagecolor{bgdark}
\color{textwhite}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{primary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{gold}\bfseries\arabic*.}}

% ── Figure macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{26}{32}\selectfont\color{textsecondary}\textit{#3}}\vspace{2mm}%
}

% ── Stat callout helper ──
\newcommand{\statbox}[3]{%
  \begin{minipage}[c]{#1\linewidth}\centering
    \colorbox{statbg}{\parbox{0.92\linewidth}{%
      \centering\vspace{10pt}%
      {\fontsize{72}{86}\selectfont\bfseries\color{#3} #2}%
      \vspace{10pt}%
    }}%
  \end{minipage}%
}

% ── Sub-header helper ──
\newcommand{\subheader}[1]{%
  {\fontsize{36}{44}\selectfont\bfseries\color{primary} #1}\par\vspace{6pt}%
}

% ── Card styles (dark theme with left accent stripe) ──
\tcbset{
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bgcard,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=bluebg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={secondary!30},
    valign=top, drop shadow={opacity=0.3},
    colupper=textwhite,
  },
  greencard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bgcard,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=greenbg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={accent!30},
    valign=top, drop shadow={opacity=0.3},
    colupper=textwhite,
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bgcardalt,
    borderline west={5pt}{0pt}{primary},
    left=16pt, right=14pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=bgcard,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={primary!30},
    valign=top, drop shadow={opacity=0.3},
    colupper=textwhite,
  },
  goldcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bgcard,
    borderline west={5pt}{0pt}{gold},
    left=16pt, right=14pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{gold},
    coltitle=gold, colbacktitle=goldbg,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={gold!30},
    valign=top, drop shadow={opacity=0.3},
    colupper=textwhite,
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primarydark!25!bgdark,
    borderline west={6pt}{0pt}{primary},
    left=16pt, right=14pt, top=8pt, bottom=8pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{textwhite},
    coltitle=textwhite, colbacktitle=primarydark,
    toptitle=8pt, bottomtitle=8pt,
    valign=top, drop shadow={opacity=0.35},
    colupper=textwhite,
  },
}

