      {\fontsize{28}{34}\selectfont\color{textsecondary} Top 10 Combined Active}\\[4pt]
      {\fontsize{28}{34}\selectfont\bfseries\color{accent} $\blacktriangle$ +595 MoM}%
      \vspace{12pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.22\linewidth}\centering
    \colorbox{statbg}{\parbox{0.92\linewidth}{%
      \centering\vspace{12pt}%
